@app.get('/api/invoices/{invoice_number}/pdf')
async def download_invoice_pdf(
    invoice_number: str,
    db: AsyncSession = Depends(get_db_session),
    user: User = Depends(get_authenticated_user)
):
    stmt = select(Invoice).where(Invoice.invoice_number == invoice_number, Invoice.customer_id == user.id)
    res = await db.execute(stmt)
    invoice = res.scalar_one_or_none()
    if not invoice or not os.path.exists(invoice.pdf_disk_path):
        raise HTTPException(status_code=404, detail="Invoice document not found")

    return FileResponse(
        path=invoice.pdf_disk_path,
        media_type="application/pdf",
        filename=f"Invoice_{invoice_number}.pdf"
    )
